"""Training pipeline for the oil price prediction model.

Synced with `notebooks/06_training_pipeline.ipynb`:

* Loads the processed features generated by `notebooks/04_feature_engineering.ipynb`
  from S3 (Rook Ceph): s3://oilprice-features/processed_features.parquet
* Trains the same model as notebook 06: a sklearn Pipeline
  (ColumnTransformer with OneHotEncoder for categorical columns and
  passthrough for numeric columns -> RandomForestRegressor). Non-numeric
  feature columns (e.g. "season") are integer-coded beforehand, exactly like
  in the notebook, because RandomForestRegressor (sklearn 1.9.1) has no
  native categorical support and converts X strictly to float.
* Logs the run to the MLflow experiment "oilprice prediction" on the same
  tracking server as the notebook: http://mlflow.mlflow.svc.cluster.local
  (override with MLFLOW_TRACKING_URI).
* Saves the model to s3://oilprice-models/oil_price_model.pkl.
"""

import base64
import json
import os
import subprocess
import sys

import joblib
import mlflow
import mlflow.sklearn
import pandas as pd
import s3fs
from sklearn.compose import ColumnTransformer
from sklearn.ensemble import RandomForestRegressor
from sklearn.metrics import mean_squared_error
from sklearn.model_selection import train_test_split
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import OneHotEncoder

FEATURES_S3_PATH = "s3://oilprice-features/processed_features.parquet"
MODEL_S3_PATH = "s3://oilprice-models/oil_price_model.pkl"
MLFLOW_EXPERIMENT = "oilprice prediction"
# Same tracking server as notebook 06 ("Set up MLflow Experiment" cell)
MLFLOW_TRACKING_URI_DEFAULT = "http://mlflow.mlflow.svc.cluster.local"

# Must match AGG_FEATURES + RT_FEATURES in 04_feature_engineering.ipynb
AGG_FEATURES = [
    "price_mean_7d", "price_std_30d",
    "demand_mean_7d", "demand_mean_30d",
    "month", "season", "month_sin", "month_cos", "seasonal_index", "price_mean_dow_4w",
]
RT_FEATURES = ["current_price", "current_demand"]
FEATURES = AGG_FEATURES + RT_FEATURES
TARGET = "target_next_week_price"

N_ESTIMATORS = 100
TEST_SIZE = 0.2
RANDOM_STATE = 42


def get_s3_options() -> dict:
    """Read S3 credentials from the Rook-generated secret (namespace rook-ceph).

    The secret values are base64-encoded. s3fs does NOT read FSSPEC_S3_*
    environment variables, so credentials must be passed explicitly:
    https://s3fs.readthedocs.io/en/latest/index.html#s3-compatible-storage
    """
    out = subprocess.run(
        [
            "kubectl", "-n", "rook-ceph", "get", "secret",
            "rook-ceph-object-user-objectstore-objectstore-user",
            "-o", "json",
        ],
        capture_output=True,
        text=True,
        check=True,
    ).stdout
    secret_data = json.loads(out)["data"]

    access_key = base64.b64decode(secret_data["AccessKey"]).decode()
    secret_key = base64.b64decode(secret_data["SecretKey"]).decode()
    endpoint = base64.b64decode(secret_data["Endpoint"]).decode()
    print("S3 endpoint:", endpoint)

    return {"key": access_key, "secret": secret_key, "endpoint_url": endpoint}


def load_features(s3_options: dict) -> pd.DataFrame:
    """Load the processed-features parquet written to S3 by 04_feature_engineering.ipynb."""
    s3 = s3fs.S3FileSystem(**s3_options)
    if not s3.exists(FEATURES_S3_PATH):
        raise FileNotFoundError(
            f"Processed features not found at {FEATURES_S3_PATH}. "
            "Run notebooks/04_feature_engineering.ipynb first."
        )
    df = pd.read_parquet(FEATURES_S3_PATH, storage_options=s3_options)
    print(f"Loaded {len(df)} rows, {len(df.columns)} columns from {FEATURES_S3_PATH}")
    return df


def prepare_data(df: pd.DataFrame):
    """Split features and target (labels target_* are NOT features -> no leakage)."""
    missing = [c for c in FEATURES + [TARGET] if c not in df.columns]
    if missing:
        raise ValueError(f"Missing columns in dataset: {missing}")

    print("Missing values per column:")
    print(df.isnull().sum().to_string())

    df = df.dropna(subset=FEATURES + [TARGET])
    X = df[FEATURES].copy()
    # Non-numeric feature columns (e.g. "season") -> integer codes:
    # RandomForestRegressor (sklearn 1.9.1) has no native categorical support
    # and converts X strictly to float, so strings must be encoded first.
    for col in X.columns:
        if not pd.api.types.is_numeric_dtype(X[col]):
            X[col] = X[col].astype("category").cat.codes
    y = df[TARGET]
    print(f"X: {X.shape} | y: {y.shape}")
    return X, y


def build_model(X_train: pd.DataFrame):
    """Build the exact model used in notebook 06 (cell: Train Model).

    Mirrors the notebook: categorical columns (dtype object/category/string)
    are one-hot encoded, everything else is passed through. After the integer
    coding in prepare_data the categorical list is empty, so the OneHotEncoder
    is a no-op -- the model structure stays identical to the notebook's.
    """
    categorical_cols = X_train.select_dtypes(include=["object", "category", "string"]).columns
    numeric_cols = X_train.columns.difference(categorical_cols)

    preprocessor = ColumnTransformer(
        transformers=[
            ("categorical", OneHotEncoder(handle_unknown="ignore"), categorical_cols),
            ("numeric", "passthrough", numeric_cols),
        ]
    )
    return make_pipeline(
        preprocessor,
        RandomForestRegressor(n_estimators=N_ESTIMATORS, random_state=RANDOM_STATE),
    )


def save_model_to_s3(model, s3_options: dict) -> None:
    s3 = s3fs.S3FileSystem(**s3_options)
    with s3.open(MODEL_S3_PATH, "wb") as f:
        joblib.dump(model, f)
    print(f"Model saved to {MODEL_S3_PATH}")


def main() -> int:
    try:
        s3_options = get_s3_options()
        df = load_features(s3_options)
    except Exception as e:
        print(f"Error loading data: {e}", file=sys.stderr)
        return 1

    X, y = prepare_data(df)

    X_train, X_test, y_train, y_test = train_test_split(
        X, y, test_size=TEST_SIZE, random_state=RANDOM_STATE
    )

    # MLflow: same tracking server as notebook 06 unless overridden
    tracking_uri = os.environ.get("MLFLOW_TRACKING_URI") or MLFLOW_TRACKING_URI_DEFAULT
    mlflow.set_tracking_uri(tracking_uri)
    mlflow.set_experiment(MLFLOW_EXPERIMENT)
    # Autolog must be active BEFORE model.fit(): it logs the model exactly once
    # (name "model") together with the training-dataset association. An explicit
    # mlflow.sklearn.log_model() call on top of that would log a second,
    # duplicate model WITHOUT the dataset association.
    mlflow.autolog()

    model = build_model(X_train)
    with mlflow.start_run():
        model.fit(X_train, y_train)
        predictions = model.predict(X_test)
        mse = mean_squared_error(y_test, predictions)

        mlflow.log_param("model_type", "Pipeline(ColumnTransformer + RandomForestRegressor)")
        mlflow.log_param("n_estimators", N_ESTIMATORS)
        mlflow.log_param("test_size", TEST_SIZE)
        mlflow.log_param("random_state", RANDOM_STATE)
        mlflow.log_metric("mse", mse)

    save_model_to_s3(model, s3_options)
    print(f"MSE: {mse}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
